update public.content set body_json=jsonb_set(coalesce(body_json,'{}'::jsonb),'{blocks}',coalesce(body_json->'blocks','[]'::jsonb) || '[{"type":"heading","level":2,"text":"11. العودة إلى الاستخدام أو التعثر: خطة تمنع الأسرة من الانهيار"},{"type":"paragraph","text":"وجود احتمال للعودة إلى الاستخدام لا يعني توقع الفشل، لكنه سبب لبناء خطة قبل الأزمة. يجب تحديد المؤشرات التي تستدعي تواصلًا مع الفريق العلاجي، وما الذي تستطيع الأسرة ملاحظته دون مراقبة مفرطة، ومن يتولى الأطفال أو المال أو النقل إذا انخفضت القدرة الوظيفية، وما الحالات التي تحتاج تقييمًا عاجلًا. الخطة تُراجع مع تغير المرحلة العلاجية ونوع المادة والحالة الطبية، ولا تُبنى على افتراض أن كل تغير مزاجي يعني عودة إلى الاستخدام."},{"type":"paragraph","text":"بعد التعثر، يفيد سؤالان منفصلان: ما الذي يحتاجه الشخص علاجيًا الآن؟ وما الذي تحتاجه الأسرة حتى تبقى آمنة وقادرة على العمل؟ قد يحتاج الأول تعديل مستوى الرعاية أو الخطة، بينما تحتاج الأسرة إعادة تفعيل حدود مؤقتة أو دعمًا إضافيًا. دمج السؤالين في نقاش واحد عن الذنب يجعل القرارات أبطأ وأكثر تصعيدًا."},{"type":"heading","level":2,"text":"12. المال والعمل والسكن: التعافي يحتاج بنية حياة"},{"type":"paragraph","text":"الاستقرار الأسري لا يُقاس بالمشاعر فقط. الديون، الإيجار، العمل، المواصلات، وثائق الهوية، ورعاية الأطفال قد تحدد قدرة الأسرة على الحفاظ على العلاج. يمكن إنشاء جدول للالتزامات الأساسية: ما المستحق خلال ثلاثين يومًا، ما الذي يمكن تفاوضه، من يملك صلاحية الدفع، وما المصروفات التي تحتاج موافقة مشتركة. عند وجود تاريخ من الاستغلال أو ديون كبيرة قد تحتاج الأسرة مشورة مالية أو قانونية مستقلة."},{"type":"paragraph","text":"العودة إلى العمل أو الدراسة مهمة للتعافي لكنها قد تزيد الضغط إذا حدثت دفعة واحدة. يمكن التفكير في تدرج واقعي يوازن العلاج والنوم والمسؤوليات. كما أن السكن يجب أن يُناقش بمعايير واضحة: الأمان، الاستقرار، قرب الخدمة، العلاقات داخل المنزل، وقواعد المشاركة. لا ينبغي استخدام السكن أو المال كسلاح لإجبار شخص على الإفصاح عن تفاصيل علاجية لا يحق للأسرة طلبها."},{"type":"heading","level":2,"text":"13. كيف نقيس تعافي الأسرة؟"},{"type":"paragraph","text":"قياس التعافي يمنع الاعتماد على الانطباع اللحظي. يمكن تسجيل مؤشرات شهرية بسيطة: عدد الأزمات التي عطلت العمل أو المدرسة، جودة النوم، النزاعات المالية، الغياب عن الالتزامات، استخدام الخدمات الصحية، شعور كل فرد بالأمان، شدة عبء مقدم الرعاية، انتظام روتين الأطفال، وجود وقت اجتماعي طبيعي، وقدرة الأسرة على حل مشكلة دون تصعيد. لا توجد ضرورة لتحويل المنزل إلى عيادة أو جمع بيانات يومية مرهقة؛ المطلوب مؤشرات قليلة تخدم القرار."},{"type":"paragraph","text":"ومن المهم ألا يكون الامتناع عن التعاطي المؤشر الوحيد. قد يتحسن استخدام المواد بينما تبقى الأسرة منهكة أو خائفة، وقد تتحسن صحة الأسرة وحدودها حتى قبل أن يدخل الشخص العلاج. هذا ليس تناقضًا؛ إنه يوضح أن نتائج الأسرة والشخص مترابطة لكنها ليست متطابقة. التقييم الجيد يحترم الاثنين."},{"type":"heading","level":3,"text":"لوحة نتائج شهرية للأسرة"},{"type":"list","ordered":false,"items":["السلامة: هل حدثت أزمة أو خوف أو تهديد أثّر في المنزل؟","الوظيفة: هل استمر العمل أو الدراسة والروتين الأساسي؟","الصحة: هل تحسن النوم والرعاية الصحية والضيق لدى أفراد الأسرة؟","العلاقة: هل انخفضت النزاعات المتكررة وهل أصبحت الاتفاقات أوضح؟","الاستقلال: هل عاد لكل فرد وقت ومساحة وقرارات تخصه؟","الخدمات: هل وصل من يحتاج إلى علاج أو دعم مناسب في الوقت المناسب؟"]},{"type":"heading","level":2,"text":"14. خطة 30 و90 يومًا لإعادة بناء الحياة الأسرية"},{"type":"paragraph","text":"في الثلاثين يومًا الأولى يكون التركيز على تثبيت الأساس: خريطة الأثر، السلامة، المسؤوليات الضرورية، المواعيد، المال الأساسي، روتين الأطفال، وقنوات التواصل. لا حاجة لفتح كل ملفات الماضي. يمكن اختيار اتفاقين أو ثلاثة فقط وتجربتها ثم مراجعتها. كما يُحدد لكل فرد مصدر دعم مستقل، لأن الاعتماد الكامل على الجلسة العائلية قد يجعل احتياجات بعض الأشخاص غير مرئية."},{"type":"paragraph","text":"بين اليوم 30 و90 يمكن الانتقال إلى أهداف أعمق: توزيع أكثر عدلًا للمسؤوليات، عودة العمل أو الدراسة، استعادة نشاط اجتماعي، معالجة بعض آثار الديون، تحديد خطوات بناء الثقة، وبدء علاج أسري أو زوجي عندما يكون مناسبًا. في نهاية الفترة تُراجع الخطة: ما الذي أصبح طبيعيًا؟ ما الذي ما زال يستهلك الأسرة؟ ما الخدمة التي يمكن تقليلها، وما الخدمة التي تحتاج تعزيزًا؟ الهدف ليس إنهاء التعافي في تسعين يومًا بل تحويله من استجابة أزمة إلى نظام قابل للاستمرار."},{"type":"heading","level":2,"text":"15. أخطاء شائعة تضعف تعافي الأسرة"},{"type":"list","ordered":false,"items":["اعتبار توقف التعاطي سببًا كافيًا لإلغاء كل الحدود فورًا.","مطالبة الطرف المتضرر بالثقة أو المسامحة قبل أن يكون مستعدًا.","تحويل الأطفال إلى مراقبين أو رسل بين البالغين.","إهمال صحة مقدم الرعاية لأن «المريض هو الأولوية».","الخلط بين دعم العلاج وبين امتلاك حق الوصول إلى كل تفاصيله السرية.","جمع المال والعلاقة والأخطاء القديمة وخطة العلاج في نقاش واحد طويل.","استخدام الدعم المالي أو السكني للإكراه بدل وضع شروط سلامة واضحة ومشروعة.","افتراض أن كل أسرة تحتاج جلسات مشتركة حتى عند وجود خوف أو إكراه أو عنف.","قياس النجاح فقط بعدد الأيام دون استخدام مواد وإهمال النوم والعمل والأطفال والعلاقات.","الانتظار حتى الأزمة التالية قبل تحديد من سيفعل ماذا."]},{"type":"faq","items":[{"question":"هل تعافي الأسرة يعتمد على تعافي الشخص من الإدمان؟","answer":"المساران مرتبطان لكنهما غير متطابقين. تستطيع الأسرة تحسين حدودها وصحتها وروتينها والوصول إلى الدعم حتى إذا كان الشخص لم يبدأ العلاج أو كانت رحلته غير مستقرة. وهذا يقلل أن تصبح حياة الجميع معلقة بنتيجة شخص واحد."},{"question":"هل يجب أن أسامح حتى أساعد على التعافي؟","answer":"لا. المساعدة لا تتطلب مشاعر محددة ولا موعدًا للمسامحة. يمكن وضع حدود واحترام العلاج والتعامل بإنصاف مع بقاء الألم أو عدم الثقة. إصلاح العلاقة قرار تدريجي وليس شرطًا طبيًا."},{"question":"هل يحق للأسرة معرفة كل ما يقوله الشخص للمعالج؟","answer":"لا بصورة تلقائية. العلاج له قواعد خصوصية وموافقة تختلف حسب البلد والعمر والخدمة. يمكن الاتفاق على المعلومات العملية التي يحتاجها أفراد الأسرة لدعم الخطة من دون تحويل المشاركة الأسرية إلى تنازل كامل عن الخصوصية."},{"question":"هل العلاج الأسري مفيد لكل حالات الإدمان؟","answer":"ليس نموذجًا واحدًا لكل الحالات. توجد أدلة على فائدة تدخلات أسرية مختلفة في سياقات متعددة، لكن الملاءمة تعتمد على العمر ونوع المشكلة والعلاقة والأمان والأهداف وتدريب مقدم الخدمة. وجود عنف أو إكراه يحتاج تقييمًا خاصًا قبل الجلسات المشتركة."},{"question":"ماذا أفعل إذا رفض الشخص العلاج؟","answer":"يمكنك طلب دعم مهني لنفسك، ضبط الحدود، حماية الأطفال والمال، وتحسين أسلوب التواصل. توجد تدخلات منظمة مثل CRAFT تهدف إلى دعم أفراد الأسرة وزيادة فرص الارتباط بالعلاج، لكنها ليست ضمانًا ولا بديلًا عن خدمات الأزمات عند وجود خطر."},{"question":"كيف نعيد الثقة بعد الكذب المرتبط بالتعاطي؟","answer":"بالسلوك المتكرر والشفاف في الاتفاقات التي تمس الأسرة: المواعيد، المال، المسؤوليات، والإبلاغ المبكر عن التغيرات. لا يلزم تفتيش دائم، ولا تعود الثقة بقرار واحد أو وعد واحد."},{"question":"هل يجب أن أخبر الأطفال عن الإدمان؟","answer":"يحتاج الأطفال عادة معلومات صادقة ومناسبة للعمر تشرح أن المشكلة ليست خطأهم وأن البالغين مسؤولون عن العلاج والسلامة. مقدار التفاصيل يعتمد على العمر والظروف، بينما يبقى الروتين والاستقرار وعدم تحميل الطفل دور المراقب أولوية."},{"question":"كيف أعرف أنني كمقدم رعاية بدأت أتعافى؟","answer":"انظر إلى نومك وصحتك وعملك وعلاقاتك وقدرتك على وضع حدود وامتلاك وقت لا يدور حول الأزمة. تحسن هذه الجوانب نتيجة مهمة بذاتها وليس خيانة للشخص الذي تحبه."},{"question":"ماذا نفعل إذا عاد الاستخدام بعد فترة تحسن؟","answer":"طبّقوا خطة مسبقة تفصل الاحتياجات العلاجية للشخص عن احتياجات السلامة والوظيفة للأسرة. راجعوا مستوى الرعاية، الحدود المؤقتة، الأطفال والمال، وتجنبوا تحويل الحدث إلى جلسة لوم طويلة تؤخر القرار."},{"question":"كم يستغرق تعافي الأسرة؟","answer":"لا يوجد جدول واحد. بعض الوظائف اليومية تتحسن خلال أسابيع، بينما الثقة والعلاقات والآثار المالية أو النفسية قد تحتاج أشهرًا أو أكثر. الأفضل متابعة مؤشرات عملية كل شهر وتعديل الخطة بدل انتظار لحظة يقال فيها إن الأسرة «تعافت بالكامل»."}]}]'::jsonb,true), updated_at=now() where slug='addiction-family-recovery-caregiver-wellbeing' and status='draft';
commit;
